_FIELDS = ("record_dir", "segment", "nsig", "frames", "abp_index", "abp_init", "abp_checksum",
           "hea_bytes", "hea_sha256", "dat_bytes", "dat_sha256")


def segment_rows() -> list[dict]:
    rows = []
    for t in SEGMENTS:
        r = dict(zip(_FIELDS, t))
        r["record"] = r["record_dir"].strip("/").split("/")[-1]
        rows.append(r)
    return rows
